// Update legacy pixel-budget assertions to reflect the new measured geometry.
// Preserve meaningful tests of compact-v-normal height and selector clearance.
use std::{env,fs,path::PathBuf};
mod previous{include!("build_v1385_followup_settings.rs");pub fn run(){main();}}
fn exact(s:&mut String,old:&str,new:&str,id:&str){assert_eq!(s.matches(old).count(),1,"follow-up test {id}: anchor missing/ambiguous");*s=s.replacen(old,new,1);}
fn main(){previous::run();let out=PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR"));let file=out.join("feature_overlays_v170_fixed.rs");let mut src=fs::read_to_string(&file).expect("read native tests");exact(&mut src,"assert_eq!(overlay_min_height_mode(Kind::Dps,100,true),180);assert_eq!(overlay_min_height_mode(Kind::Dps,100,false),220);","let compact=overlay_min_height_mode(Kind::Dps,100,true);let normal=overlay_min_height_mode(Kind::Dps,100,false);assert!(compact>=180);assert!(normal>compact);assert!(normal-compact>=30);","R01 preserve comparative minimum height");fs::write(file,src).expect("write test");let file=out.join("ui_meter_qa_tests_raid_v1345.rs");let mut src=fs::read_to_string(&file).expect("read meter QA tests");exact(&mut src,"assert!(selector.rect.right - selector.rect.left >= 148);","assert!(selector.rect.right - selector.rect.left >= audit_label_width(&s,selector.label,24));","R02 require actual measured selector text and padding");fs::write(file,src).expect("write meter QA");println!("cargo:rerun-if-changed=build/legacy/build_v1386_followup_test_contract.rs");}
